ALTER TABLE profiles
    ADD COLUMN school_name varchar(100),
    ADD COLUMN college_major varchar(100),
    ADD COLUMN grade_level varchar(30),
    ADD COLUMN teach_grades jsonb NOT NULL DEFAULT '[]',
    ADD COLUMN teach_subjects jsonb NOT NULL DEFAULT '[]',
    ADD COLUMN years_exp varchar(80),
    ADD COLUMN teaching_style_tags jsonb NOT NULL DEFAULT '[]',
    ADD COLUMN cases_json jsonb NOT NULL DEFAULT '[]',
    ADD COLUMN trial_policy text NOT NULL DEFAULT '暂不支持试课',
    ADD COLUMN resume_pdf_url text,
    ADD COLUMN resume_pdf_name varchar(180);

CREATE TABLE teacher_resume_files (
    account_id uuid PRIMARY KEY REFERENCES profiles(account_id) ON DELETE CASCADE,
    file_id uuid UNIQUE NOT NULL,
    content bytea NOT NULL CHECK (octet_length(content) BETWEEN 1 AND 5242880)
);

