), seed AS (SELECT id::uuid, account_key, fields::jsonb AS f FROM fixtures)
UPDATE profiles p SET college_major=f->>'collegeMajor', grade_level=f->>'gradeLevel',
    teach_grades=f->'teachGrades', teach_subjects=f->'teachSubjects', years_exp=f->>'yearsExp',
    teaching_style_tags=f->'teachingStyleTags', cases_json=f->'casesJson', trial_policy=f->>'trialPolicy',
    version=version+1, updated_at=now()
FROM seed JOIN accounts a ON a.id=seed.id AND a.account_key=seed.account_key
WHERE p.account_id=a.id AND a.business_identity='TUTOR' AND a.email=seed.account_key || '@seed.linke.invalid';
